package authz

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"
)

type Role int

const (
	RoleUser  Role = 1
	RoleAdmin Role = 2
)

type Session struct {
	UserID    string `json:"user_id"`
	Role      Role   `json:"role"`
	ExpiresAt int64  `json:"expires_at"`
}

type AuthContext struct {
	mu       sync.RWMutex
	session  *Session
	resolved bool
	success  bool
	errCh    chan error
}

func NewAuthContext() *AuthContext {
	return &AuthContext{
		errCh: make(chan error, 1),
	}
}

func (ac *AuthContext) ResolveAsync(ctx context.Context, tokenData []byte) {
	go func() {
		var sess Session
		if err := deserializeSession(tokenData, &sess); err != nil {
			ac.errCh <- err
			return
		}
		ac.mu.Lock()
		ac.session = &sess
		ac.resolved = true
		ac.success = true
		ac.mu.Unlock()
		ac.errCh <- nil
	}()
}

func (ac *AuthContext) WaitForResolution(timeout time.Duration) error {
	select {
	case err := <-ac.errCh:
		if err != nil {
			ac.mu.Lock()
			ac.resolved = true
			ac.success = false
			ac.mu.Unlock()
		}
		return err
	case <-time.After(timeout):
		ac.mu.Lock()
		ac.resolved = true
		ac.success = false
		ac.mu.Unlock()
		return fmt.Errorf("session resolution timed out")
	}
}

func (ac *AuthContext) GetSession() *Session {
	ac.mu.RLock()
	defer ac.mu.RUnlock()
	return ac.session
}

func (ac *AuthContext) IsResolved() bool {
	ac.mu.RLock()
	defer ac.mu.RUnlock()
	return ac.resolved
}

func (ac *AuthContext) IsSuccess() bool {
	ac.mu.RLock()
	defer ac.mu.RUnlock()
	return ac.success
}

// sessionSigningKey is loaded from the environment. Tokens must be signed
// with this key so that clients cannot forge arbitrary sessions.
func sessionSigningKey() ([]byte, error) {
	key := os.Getenv("SESSION_SIGNING_KEY")
	if len(key) < 32 {
		return nil, fmt.Errorf("session signing key not configured")
	}
	return []byte(key), nil
}

// verifyToken expects tokenData in the form "<base64url(payload)>.<base64url(hmac)>"
// where hmac = HMAC-SHA256(payload, key). It returns the raw payload bytes on
// success. This prevents forgery of session data supplied by clients.
func verifyToken(tokenData []byte) ([]byte, error) {
	key, err := sessionSigningKey()
	if err != nil {
		return nil, err
	}

	token := string(tokenData)
	dotIdx := -1
	for i := len(token) - 1; i >= 0; i-- {
		if token[i] == '.' {
			dotIdx = i
			break
		}
	}
	if dotIdx <= 0 || dotIdx == len(token)-1 {
		return nil, fmt.Errorf("malformed session token")
	}

	payloadB64 := token[:dotIdx]
	sigB64 := token[dotIdx+1:]

	payload, err := base64.RawURLEncoding.DecodeString(payloadB64)
	if err != nil {
		return nil, fmt.Errorf("invalid token payload encoding")
	}
	providedSig, err := base64.RawURLEncoding.DecodeString(sigB64)
	if err != nil {
		return nil, fmt.Errorf("invalid token signature encoding")
	}

	mac := hmac.New(sha256.New, key)
	mac.Write(payload)
	expectedSig := mac.Sum(nil)

	if !hmac.Equal(providedSig, expectedSig) {
		return nil, fmt.Errorf("session token signature verification failed")
	}

	return payload, nil
}

func deserializeSession(data []byte, sess *Session) error {
	payload, err := verifyToken(data)
	if err != nil {
		return fmt.Errorf("invalid session data: %w", err)
	}
	if err := json.Unmarshal(payload, sess); err != nil {
		return fmt.Errorf("invalid session data: %w", err)
	}
	if sess.ExpiresAt < time.Now().Unix() {
		return fmt.Errorf("session expired")
	}
	return nil
}

func RequireRole(required Role, ac *AuthContext) bool {
	if !ac.IsResolved() || !ac.IsSuccess() {
		return false
	}
	sess := ac.GetSession()
	if sess == nil {
		return false
	}
	return sess.Role >= required
}

func AdminHandler(w http.ResponseWriter, r *http.Request) {
	tokenData := []byte(r.Header.Get("X-Session-Token"))

	ac := NewAuthContext()
	ac.ResolveAsync(r.Context(), tokenData)

	err := ac.WaitForResolution(50 * time.Millisecond)
	if err != nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if !RequireRole(RoleAdmin, ac) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"admin_data": "secret_configuration_values"}`))
}

func SetupRoutes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/admin/config", AdminHandler)
	return mux
}
